#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn table_is_sorted_by_map_id() {
        assert!(TABLE.windows(2).all(|w| w[0].0 < w[1].0));
    }

    #[test]
    fn continents_are_not_instances_and_every_instance_is_named() {
        // Eastern Kingdoms and Kalimdor are open world; a tripwire
        // against the column changing meaning.
        assert_eq!(instance_name(0), None);
        assert_eq!(instance_name(1), None);
        assert_eq!(instance_name(u32::MAX), None);
        assert!(TABLE.iter().all(|e| !e.1.is_empty()));
    }
}
